                for m in bases[r-e]:
                    row={tuple(sorted(m+k)):v for k,v in rel.items()}
                    rows.append([row.get(k,0) for k in bases[r]])
        rank=rank_mod(rows,len(bases[r]));print('FZ',r,'vars',len(bases[r]),'rank',rank,'dim',len(bases[r])-rank,flush=True)
